/* ============================================
   SECTION TITLE COMPONENT
   Heading with divider line, optional trailing content
   ============================================ */

.ds-section-title {
  display: flex;
  align-items: baseline;
  gap: var(--gap-400);
  border-bottom: var(--border-025) solid var(--color-divider);
  padding-bottom: var(--padding-500);
}

/* Divider-less variant: for headings above content that draws its own
   lines, where a second rule would double up. The generous clearance
   the divider needed drops to a small breathing gap. */
.ds-section-title--no-divider {
  border-bottom: none;
  padding-bottom: var(--padding-400);
}

/* ============================================
   HEADING
   ============================================ */

.ds-section-title__heading {
  font-family: var(--font-heading-2-family);
  font-size: var(--font-heading-2-size);
  font-weight: var(--font-heading-2-weight);
  line-height: var(--font-heading-2-line-height);
  letter-spacing: var(--font-heading-2-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   TRAILING CONTENT (count, badge, metadata)
   ============================================ */

.ds-section-title__trailing {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  color: var(--color-text-tertiary);
}

import React from "react";
import "./SectionTitle.css";

export interface SectionTitleProps {
  /** Section heading text */
  title: string;
  /** Optional trailing content (count, badge, metadata) */
  trailing?: React.ReactNode;
  /** Whether to draw the bottom divider line. Set false above content that draws its own lines (bordered tables, calendars), so the section separates by whitespace alone. */
  divider?: boolean;
  /** Additional CSS classes */
  className?: string;
}

export function SectionTitle({
  title,
  trailing,
  divider = true,
  className,
}: SectionTitleProps) {
  const classes = [
    "ds-section-title",
    !divider && "ds-section-title--no-divider",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={classes}>
      <h2 className="ds-section-title__heading">{title}</h2>
      {trailing !== undefined && trailing !== null && (
        <span className="ds-section-title__trailing">{trailing}</span>
      )}
    </div>
  );
}
